    private function upgrade(string $slug, string $starterBody, array $content): void
    {
        $page = ContentPage::query()->where('slug', $slug)->first();

        if (! $page) {
            ContentPage::query()->create(array_merge($content, ['slug' => $slug]));

            return;
        }

        // Upgrade only the known starter copy. CMS-managed editorial changes always win.
        if ($page->translation('body', 'en') === $starterBody) {
            $page->update($content);
        }
    }

